#include <fc/crypto/rand.hpp>
namespace key_client {
constexpr auto account="eosio.key"_n;
inline bool is_public_key(const string& s){return s.starts_with("PUB_")||s.starts_with("EOS");}
inline public_key_type k1(const string& s){public_key_type k(s);FC_ASSERT(k.which()==0&&k.valid(),"Valid K1 key required");return k;}
inline digest_type random_id(){digest_type id;fc::rand_bytes(reinterpret_cast<char*>(id.data()),32);return id;}
inline void exact(const fc::variant& v,const std::vector<string>& fields){FC_ASSERT(v.is_object()&&v.get_object().size()==fields.size(),"Unexpected protocol fields");for(const auto& f:fields)FC_ASSERT(v.get_object().contains(f.c_str()),"Missing protocol field ${f}",("f",f));}
inline fc::variant configuration(){auto value=call(get_table_func,fc::mutable_variant_object("json",true)("code",account)("scope",account)("table","config")("limit",1));FC_ASSERT(value["rows"].get_array().size()==1,"Wallet is not initialized");auto cfg=value["rows"].get_array().front();FC_ASSERT(cfg["version"].as_uint64()==2&&cfg["chain_id"].as<chain_id_type>()==get_info().chain_id&&cfg["fee_symbol"].as_string()=="4,AIC","Unsupported wallet domain");return cfg;}
inline asset fee_cap(const string& s){FC_ASSERT(!s.empty(),"Explicit AIC maximum fee required");auto a=asset::from_string(s);FC_ASSERT(a.get_symbol()==symbol::from_string("4,AIC")&&a.get_amount()>=0,"Nonnegative 4,AIC cap required");return a;}
inline chain::action token_transfer(name token,name sender,name recipient,const asset& amount,const string& memo){chain::action a;a.account=token;a.name="transfer"_n;a.authorization=get_account_permissions(tx_permission,{sender,"active"_n});a.data=fc::raw::pack(std::make_tuple(sender,recipient,amount,memo));return a;}
inline std::vector<chain::action> deposit(name sender,const string& recipient,name token,const asset& quantity,const string& maximum,const string& funding){auto cfg=configuration();auto key=k1(recipient);auto cap=fee_cap(maximum);FC_ASSERT(quantity.get_amount()>0,"Positive principal required");std::vector<chain::action> out;if(!funding.empty()){auto f=fee_cap(funding);FC_ASSERT(f.get_amount()>0,"Positive fee funding required");out.push_back(token_transfer(cfg["fee_contract"].as<name>(),sender,account,f,"fee"));}out.push_back(token_transfer(token,sender,account,quantity,"PK2|"+key.to_string({})+"|"+std::to_string(cap.get_amount())+"|"+random_id().str()));return out;}
inline fc::variant wallet(const public_key_type& key){auto b=fc::raw::pack(key);auto h=digest_type::hash(b.data(),b.size());auto response=call(get_table_func,fc::mutable_variant_object("json",true)("code",account)("scope",account)("table","wallets")("index_position","2")("key_type","sha256")("lower_bound",h.str())("upper_bound",h.str())("limit",2));const auto& rows=response["rows"].get_array();FC_ASSERT(rows.size()==1&&rows[0]["key"].as<public_key_type>()==key,"Sender wallet missing");return rows[0];}
inline bytes request_bytes(const string& op,const fc::variant& r){
 const bool cancel=op=="cancel"||op=="selfcancel",self=op=="selfout"||op=="selfcancel";
 FC_ASSERT(cancel||op=="ksend"||op=="withdraw"||op=="selfout","Unsupported operation");
 exact(r,cancel?std::vector<string>{"from","auth_epoch","next_epoch","request_id","relayer","reward_to","max_fee"}:std::vector<string>{"from","to","token_contract","quantity","memo","auth_epoch","request_id","relayer","reward_to","max_fee"});
 bytes out;auto append=[&](const auto& o){auto b=fc::raw::pack(o);out.insert(out.end(),b.begin(),b.end());};
 append(k1(r["from"].as_string()));
 if(!cancel){if(op=="ksend")append(k1(r["to"].as_string()));append(r["token_contract"].as<name>());if(op!="ksend")append(r["to"].as<name>());auto q=asset::from_string(r["quantity"].as_string());FC_ASSERT(q.get_amount()>0&&r["memo"].as_string().size()<=128,"Invalid principal or memo");append(q);append(r["memo"].as_string());}
 auto epoch=r["auth_epoch"].as_uint64();append(epoch);if(cancel){auto next=r["next_epoch"].as_uint64();FC_ASSERT(next>epoch,"Replacement epoch must increase");append(next);}
 auto id=r["request_id"].as<digest_type>();FC_ASSERT(id!=digest_type(),"Nonzero request ID required");append(id);auto relay=r["relayer"].as<name>(),reward=r["reward_to"].as<name>();FC_ASSERT(self?(!relay&&!reward):(relay&&relay==reward),"Invalid selected BP/reward identity");append(relay);append(reward);append(fee_cap(r["max_fee"].as_string()));return out;
}
inline digest_type digest(const transaction& tx,const fc::variant& cfg){auto b=fc::raw::pack(std::make_tuple(string("PureEOS:eosio.key:transaction"),uint32_t(2),cfg["chain_id"].as<chain_id_type>(),account,cfg["deployment"].as<digest_type>(),tx.id()));return digest_type::hash(b.data(),b.size());}
inline transaction verify_prepared(const fc::variant& p,const fc::variant& cfg){
 exact(p,{"version","chain_id","deployment","operation","request","payer","permission","reference_block_num","transaction","transaction_id","digest"});
 FC_ASSERT(p["version"].as_uint64()==2&&p["chain_id"]==cfg["chain_id"]&&p["deployment"]==cfg["deployment"],"Prepared domain mismatch");
 const auto& t=p["transaction"];exact(t,{"expiration","ref_block_num","ref_block_prefix","max_net_usage_words","max_cpu_usage_ms","delay_sec","context_free_actions","actions","transaction_extensions"});
 for(const auto& field:{"actions","context_free_actions"})for(const auto& a:t[field].get_array()){exact(a,{"account","name","authorization","data"});FC_ASSERT(a["data"].is_string(),"Raw action bytes required");for(const auto& auth:a["authorization"].get_array())exact(auth,{"actor","permission"});}
 auto tx=t.as<transaction>();FC_ASSERT(tx.actions.size()==1&&tx.context_free_actions.size()==1&&tx.transaction_extensions.empty()&&tx.delay_sec.value==0&&tx.max_cpu_usage_ms==0&&tx.max_net_usage_words.value==0&&fc::raw::pack_size(tx)<=16384,"Unsupported native transaction envelope");
 auto op=p["operation"].as_string();bool self=op=="selfout"||op=="selfcancel";auto body=request_bytes(op,p["request"]);auto payer=p["payer"].as<name>();FC_ASSERT(self?bool(payer):!payer,"Invalid native payer");if(self){auto b=fc::raw::pack(payer);body.insert(body.begin(),b.begin(),b.end());}
 auto ref=p["reference_block_num"].as_uint64();FC_ASSERT(ref>0&&ref<=UINT32_MAX&&(ref&65535)==tx.ref_block_num,"Invalid signed reference");
 auto proof=fc::raw::pack(std::make_tuple(k1(p["request"]["from"].as_string()),cfg["chain_id"].as<chain_id_type>(),cfg["deployment"].as<digest_type>(),uint32_t(ref)));
 const auto& cfa=tx.context_free_actions[0];const auto& root=tx.actions[0];auto perm=p["permission"].as<name>();
 FC_ASSERT(perm&&cfa.account==account&&cfa.name=="prove"_n&&cfa.authorization.empty()&&cfa.data==proof,"Owner proof mismatch");
 FC_ASSERT(root.account==account&&root.name==name(op)&&root.authorization.size()==1&&root.authorization[0].actor==(self?payer:p["request"]["relayer"].as<name>())&&root.authorization[0].permission==perm&&root.data==body,"Root operation mismatch");
 FC_ASSERT(tx.id()==p["transaction_id"].as<digest_type>()&&digest(tx,cfg)==p["digest"].as<digest_type>(),"Prepared digest mismatch");return tx;
}
inline transaction verify_signed(const fc::variant& b,const fc::variant& cfg){exact(b,{"prepared","owner_signature"});auto tx=verify_prepared(b["prepared"],cfg);auto sig=b["owner_signature"].as<signature_type>();FC_ASSERT(sig.which()==0&&public_key_type(sig,digest(tx,cfg))==k1(b["prepared"]["request"]["from"].as_string()),"Invalid owner signature");return tx;}
inline signature_type owner_signature(const digest_type& h,const public_key_type& key){auto sig=call(wallet_url,"/v1/wallet/sign_digest",fc::variants{fc::variant(h),fc::variant(key)}).as<signature_type>();FC_ASSERT(public_key_type(sig,h)==key,"Incorrect wallet signature");return sig;}
struct commands {
 string from,to,amount,token="eosio.token",maximum,memo,bp,input,payer,permission="keyrelay",relay_url;
 uint32_t valid_seconds=120;bool self=false,allow_http=false;
 commands(CLI::App& app){
 auto root=app.add_subcommand("key","Public-key wallet transfers; independent owner proof and extra AIC fees")->require_subcommand();
 auto prepare=root->add_subcommand("prepare","Prepare complete immutable transaction before local owner signing");
 prepare->add_option("from",from,"Sender K1 public key")->required();prepare->add_option("to",to,"Recipient public key or native account")->required();prepare->add_option("quantity",amount,"Full principal")->required();prepare->add_option("--token-contract,-c",token,"Issuing token contract");prepare->add_option("--max-fee",maximum,"Maximum total extra AIC fee")->required();prepare->add_option("--bp",bp,"Selected commercial BP");prepare->add_option("--memo",memo,"Recipient memo, <=128 bytes");prepare->add_option("--valid-seconds",valid_seconds,"Native transaction validity, 30..3500 seconds");prepare->add_flag("--self",self,"Owner self withdrawal, no BP markup");prepare->add_option("--payer",payer,"Required self withdrawal native payer");prepare->add_option("--payer-permission",permission,"Selected BP child permission or self payer permission");
 prepare->callback([this]{
 FC_ASSERT(valid_seconds>=30&&valid_seconds<=3500&&((self&&bp.empty()&&!payer.empty()&&!is_public_key(to))||(!self&&!bp.empty()&&payer.empty())),"Choose BP or self withdrawal with explicit payer");
 auto cfg=configuration();auto key=k1(from);auto source=wallet(key);auto info=get_info();auto op=self?string("selfout"):is_public_key(to)?string("ksend"):string("withdraw");if(op!="ksend")call(get_account_func,fc::mutable_variant_object("account_name",name(to)));
 fc::variant request=fc::mutable_variant_object("from",key)("to",op=="ksend"?fc::variant(k1(to)):fc::variant(name(to)))("token_contract",name(token))("quantity",to_asset(name(token),amount))("memo",memo)("auth_epoch",std::to_string(source["auth_epoch"].as_uint64()))("request_id",random_id())("relayer",bp)("reward_to",bp)("max_fee",fee_cap(maximum));
 transaction tx;tx.expiration=fc::time_point_sec(info.head_block_time+fc::seconds(valid_seconds));tx.set_reference_block(info.last_irreversible_block_id);chain::action proof;proof.account=account;proof.name="prove"_n;proof.data=fc::raw::pack(std::make_tuple(key,info.chain_id,cfg["deployment"].as<digest_type>(),info.last_irreversible_block_num));tx.context_free_actions.push_back(proof);
 chain::action action;action.account=account;action.name=name(op);auto selected=permission;if(self&&permission=="keyrelay")selected="active";action.authorization={{self?name(payer):name(bp),name(selected)}};action.data=request_bytes(op,request);if(self){auto b=fc::raw::pack(name(payer));action.data.insert(action.data.begin(),b.begin(),b.end());}tx.actions.push_back(action);
 fc::variant prepared=fc::mutable_variant_object("version",2)("chain_id",cfg["chain_id"])("deployment",cfg["deployment"])("operation",op)("request",request)("payer",self?payer:string())("permission",selected)("reference_block_num",info.last_irreversible_block_num)("transaction",tx)("transaction_id",tx.id())("digest",digest(tx,cfg));verify_prepared(prepared,cfg);std::cout<<fc::json::to_pretty_string(prepared)<<std::endl;
 });
 auto sign=root->add_subcommand("sign","Verify and sign immutable prepared transaction with local keosd");sign->add_option("prepared",input,"Prepared JSON file or JSON text")->required();sign->callback([this]{auto p=json_from_file_or_string(input);auto cfg=configuration();auto tx=verify_prepared(p,cfg);auto sig=owner_signature(digest(tx,cfg),k1(p["request"]["from"].as_string()));std::cout<<fc::json::to_pretty_string(fc::mutable_variant_object("prepared",p)("owner_signature",sig))<<std::endl;});
 auto push=root->add_subcommand("push","Sign native resource envelope without changing owner-approved transaction");push->add_option("signed-intent",input,"Signed immutable envelope")->required();add_standard_transaction_options_plus_signing(push,"selected BP child permission or self payer");push->callback([this]{auto b=json_from_file_or_string(input);auto cfg=configuration();auto tx=verify_signed(b,cfg);if(!tx_permission.empty())FC_ASSERT(get_account_permissions(tx_permission)==tx.actions[0].authorization,"Permission differs from owner-approved envelope");signed_transaction st(std::move(tx),{},std::vector<bytes>{fc::raw::pack(b["owner_signature"].as<signature_type>())});FC_ASSERT(!tx_force_unique&&tx_ref_block_num_or_id.empty()&&delaysec==0&&tx_max_cpu_usage==0&&tx_max_net_usage==0&&!tx_dry_run&&!tx_read,"Prepare and owner-sign a new envelope to change native transaction fields");FC_ASSERT(!tx_skip_sign||tx_dont_broadcast,"Skipping resource signatures requires --dont-broadcast export");if(!tx_skip_sign){fc::variant required=signing_keys_opt.get_keys().empty()?determine_required_keys(st):fc::variant(signing_keys_opt.get_keys());sign_transaction(st,required,cfg["chain_id"].as<chain_id_type>());}FC_ASSERT(st.id()==b["prepared"]["transaction_id"].as<digest_type>(),"Wallet mutated native transaction");if(tx_dont_broadcast){std::cout<<fc::json::to_pretty_string(st)<<std::endl;return;}auto result=call(push_txn_func,packed_transaction(st));return_code=get_return_code(result);if(tx_print_json)std::cout<<fc::json::to_pretty_string(result)<<std::endl;else print_result(result);});
 auto submit=root->add_subcommand("submit","Submit completed owner proof to selected HTTPS BP relay");submit->add_option("signed-intent",input,"Signed immutable envelope")->required();submit->add_option("--relay-url",relay_url,"Selected BP endpoint")->required();submit->add_flag("--allow-http-for-test",allow_http,"Allow exact loopback host only");submit->callback([this]{auto b=json_from_file_or_string(input);auto cfg=configuration();verify_signed(b,cfg);auto op=b["prepared"]["operation"].as_string();FC_ASSERT(op=="ksend"||op=="withdraw"||op=="cancel","Commercial envelope required");FC_ASSERT(std::regex_match(relay_url,std::regex(R"(https://[A-Za-z0-9.-]+(:[0-9]{1,5})?(/[A-Za-z0-9._~!$&'()*+,;=:@%/-]*)?)"))||(allow_http&&std::regex_match(relay_url,std::regex(R"(http://(127\.0\.0\.1|localhost):[0-9]{1,5}(/[A-Za-z0-9._~%/-]*)?)"))),"Valid HTTPS endpoint required; test HTTP must be exact loopback");while(!relay_url.empty()&&relay_url.back()=='/')relay_url.pop_back();eosio::client::http::config_t relay_config;std::cout<<fc::json::to_pretty_string(eosio::client::http::do_http_call(relay_config,relay_url,"/submit",b))<<std::endl;});
 }
};
}
